using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace AstroArchive {
 public partial class MainUi {
  void SmokeExternalExports(string output){
   string theme=settings.ThemeMode;int scale=settings.TextScalePercent;var defaults=settings.ExportDefaults;var paths=settings.ExternalApplicationPaths;
   try{
    settings.ExportDefaults=new Dictionary<string,string>{{"TIFF","gimp"}};
    foreach(string mode in new[]{"Dark","Light"})foreach(int textScale in new[]{100,150}){
     settings.ThemeMode=mode;settings.TextScalePercent=textScale;ApplyAppearance();ExportWindowFields fields;var finished=new Frame{Hash="finished",Kind="Stack",OriginalName="Finished Ω.tiff",Format="TIFF",Target="M45"};var dialog=ExportWindow(new ExportScope{Files=new List<Frame>{finished},Selected=true},ExportCategory.Application,out fields);
     try{dialog.Window.Show();PumpPopupLayout();VerifyWindowIcon(dialog.Window);if(SelectedApplication(fields.Application).Id!="gimp"||fields.AppRemember.IsChecked==true)throw new Exception("Export default or opt-in changed");if(fields.Application.Items.OfType<ComboBoxItem>().Count(i=>i.Tag is ExportApplication)!=8)throw new Exception("Destinations missing");if(fields.Application.Items.OfType<ComboBoxItem>().Single(i=>i.Tag is ExportApplication&&((ExportApplication)i.Tag).Id=="dss").IsEnabled)throw new Exception("DSS accepts a finished image");if(fields.Destination.IsVisible||!fields.Primary.IsEnabled||Convert.ToString(fields.Primary.Content)!="Open in app")throw new Exception("Finished-image handoff asks for a destination or cannot start");foreach(var button in PopupChildren<Button>(dialog.Window).Where(b=>b==fields.Primary||Convert.ToString(b.Content)=="Cancel"))if(!button.IsVisible||button.ActualWidth+button.Margin.Left+button.Margin.Right<button.DesiredSize.Width-0.5)throw new Exception("Export actions clipped");fields.Application.SelectedIndex=0;if(fields.Primary.IsEnabled||!fields.Problem.IsVisible)throw new Exception("Export started without an application");CapturePopup(dialog.Window,Path.Combine(output,"AstroArchive_ExportTo_"+mode+textScale+".png"));}finally{dialog.Window.Close();}
     var subs=new List<Frame>{new Frame{Hash="sub01",Kind="Light",OriginalName="sub01.fit",Format="FITS",Target="M45"},new Frame{Hash="sub02",Kind="Light",OriginalName="sub02.fit",Format="FITS",Target="M45"}};var folder=ExportWindow(new ExportScope{Files=subs,Selected=true},ExportCategory.Application,out fields);try{folder.Window.Show();PumpPopupLayout();fields.Application.SelectedItem=fields.Application.Items.OfType<ComboBoxItem>().Single(i=>i.Tag is ExportApplication&&((ExportApplication)i.Tag).Id=="siril");PumpPopupLayout();if(!fields.Destination.IsVisible||fields.AppCalibration.IsChecked==true||fields.AppUnknown.IsEnabled)throw new Exception("Folder options unsafe");fields.AppCalibration.IsChecked=true;if(!fields.AppUnknown.IsEnabled)throw new Exception("Unknown calibration option does not follow checkbox");fields.AppCalibration.IsChecked=false;if(fields.AppUnknown.IsEnabled)throw new Exception("Unknown calibration remains enabled");CapturePopup(folder.Window,Path.Combine(output,"AstroArchive_ExportTo_Folder_"+mode+textScale+".png"));}finally{folder.Window.Close();}
     PreferenceFields preferenceFields;var preferences=PreferencesDialog(Window,2,out preferenceFields);var exportFields=preferenceFields.Exports;exportFields.ApplicationOptions.IsExpanded=true;exportFields.Application.SelectedItem="AstroWizard";
     try{preferences.Window.Show();PumpPopupLayout();if(Convert.ToString(exportFields.Application.SelectedItem)!="AstroWizard")throw new Exception("Application settings focused wrong destination");exportFields.Paths["astrowizard"]="cancelled.exe";exportFields.Defaults["TIFF"]="photoshop";if(settings.ExportDefaults["TIFF"]!="gimp"||settings.ExternalApplicationPaths!=paths)throw new Exception("Cancelled settings mutated live preferences");CapturePopup(preferences.Window,Path.Combine(output,"AstroArchive_Export_Settings_"+mode+textScale+".png"));exportFields.ApplicationOptions.IsExpanded=false;exportFields.DefaultOptions.IsExpanded=true;PumpPopupLayout();if(!PopupChildren<ComboBox>(preferences.Window).Any(c=>c.IsVisible&&c.Items.Contains("Stacking Wizard")))throw new Exception("Folder default setting unreachable");}finally{preferences.Window.Close();}
    }
    File.WriteAllText(Path.Combine(output,"external-export-smoke.txt"),"PASS: eight destinations, compatible choices, type defaults, safe folder options, cancellation isolation and visible actions in both themes at 100/150% text.");
   }finally{settings.ThemeMode=theme;settings.TextScalePercent=scale;settings.ExportDefaults=defaults;settings.ExternalApplicationPaths=paths;ApplyAppearance();}
  }
 }
}
